    $('where').textContent = s ? s.name : ''; $('where').style.display = s ? '' : 'none';
    $('empty').style.display = tour.scenes.length || EXPORTED ? 'none' : 'flex';
    $('rot').classList.toggle('on', !!tour.opts.autorotate);
    $('annos').classList.toggle('on', !!tour.opts.showAnnos);
    const hint = $('hint');
    const H = {
      link: 'اضغط على الأرض أمام الباب لسهم مشي، أو على الباب نفسه',
      'dim-floor': pendingA ? 'اضغط النقطة الثانية على الأرضية' : 'اضغط النقطة الأولى على الأرضية (مثلاً زاوية الجدار عند الأرض)',
      'dim-height': pendingA ? 'اضغط أعلى الجدار أو القطعة فوق نفس النقطة' : 'اضغط أسفل الجدار أو القطعة حيث تلمس الأرض',
      'dim-free': pendingA ? 'اضغط النقطة الثانية' : 'اضغط النقطة الأولى',
      text: 'اضغط مكان النص في الصورة', icon: 'اضغط مكان الأيقونة في الصورة',
      move: 'اضغط المكان الجديد' + (getSel() && getSel().type === 'dim' ? ' (نقطتين: البداية ثم النهاية)' : '')
    };
    if (H[mode]) { hint.textContent = H[mode] + ' · Esc للإلغاء'; hint.style.display = ''; }
    else if (tour.scenes.length && !EXPORTED) { hint.textContent = 'اسحب للالتفات · العجلة للتكبير · اضغط عنصر لتعديله · Shift + ضغط على سهم الانتقال لتعديله'; hint.style.display = ''; }
    else hint.style.display = 'none';
