      const d = document.createElement('div'); d.className = 'sc' + (sc.id === cur ? ' cur' : '');
      d.innerHTML = `<img alt=""><button class="x star" title="أول غرفة">${tour.start === sc.id ? '⭐' : '☆'}</button><input><button class="x del" title="حذف">×</button>`;
