    if (!isLink && o.type === 'dim') add('لون نص المقاس', swatches(o.textColor || '#ffffff', (c, light) => set('textColor', c, light)));
    const r = document.createElement('input'); r.type = 'range'; r.min = 0.4; r.max = 3; r.step = 0.1; r.value = o.size;
    r.oninput = () => set('size', +r.value, true);
